"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[357],{1177:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>l});var o=n(5512),a=n(4848),i=n(8453);const s={date:new Date("2022-05-10T09:30:00.000Z"),description:"In this essay, I want to summarize my experience with the insights I collected throughout the year. Some of them might be obvious to a more experienced audience. But for me, some of them were kind of revelations, and some of them were hugely underestimated initially.",slug:"product-manager-year-one",tags:["Product Management","Community & Insights"],title:"Product Manager: Year One"},r="Product Manager: Year One",h={authorsImageUrls:[]},l=[{value:"Lack of resources is permanent - live with that",id:"lack-of-resources-is-permanent---live-with-that",level:2},{value:"&quot;Lights-on&quot; work is a real threat to product development",id:"lights-on-work-is-a-real-threat-to-product-development",level:2},{value:"Hell of constant replanning",id:"hell-of-constant-replanning",level:2},{value:"Being without mentorship sucks",id:"being-without-mentorship-sucks",level:2},{value:"Afterword",id:"afterword",level:2}];function d(e){const t={em:"em",h2:"h2",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Cover",src:n(1632).A+"",width:"640",height:"640"})}),"\n",(0,a.jsx)(t.p,{children:"One year has passed since I was promoted to a Product Manager position: first six months as an Associate (a Junior grade), and then I stepped in as a fully-fledged Product Manager. And that was a drastic shift that made me revisit some aspects of my work and added a new dimension to my view on product development."}),"\n",(0,a.jsx)(t.p,{children:"In this essay, I want to summarize my experience with the insights I collected throughout the year. Some of them might be obvious to a more experienced audience. But for me, some were revelations, and some were hugely underestimated initially. It is a good exercise to conduct such a personal retrospective, and others can benefit from that as well."}),"\n",(0,a.jsx)(t.h2,{id:"lack-of-resources-is-permanent---live-with-that",children:"Lack of resources is permanent - live with that"}),"\n",(0,a.jsx)(t.p,{children:"During the meetings with senior management, some Product Managers from other teams always complained about needing more people to complete their goals. It is a big problem that cannot be resolved immediately. But at some point, that becomes irritating. Lacking human resources should not become a constant excuse for missing business objectives."}),"\n",(0,a.jsx)(t.p,{children:"I was also among the complainers at first. Then I realized a better strategy to focus on what you can achieve with the current amount of people in the team. Some objectives require a lot of people involved to get the right things done at the right time. But some of the objectives also can be decomposed and addressed with a current team capacity. Also, a business need can be handled in many ways, not always with hundreds of dev hours or story points spent on new features. You need some space to think out of the box and have the trust of the senior stakeholders in you and your team to find the right solution within current constraints."}),"\n",(0,a.jsx)(t.p,{children:'I asked myself, "What should we not do or stop doing to achieve something?" instead of "What should we do?". Do more with less. That is my motto right now. I know what I would do with more developers in my teams. But I have a strategy in case of decreasing the team\'s capacity even more.'}),"\n",(0,a.jsx)(t.h2,{id:"lights-on-work-is-a-real-threat-to-product-development",children:'"Lights-on" work is a real threat to product development'}),"\n",(0,a.jsx)(t.p,{children:"Support activities and tech debt can bite off a large piece of a team's capacity and defocus them from new product functionality. You can't avoid this, unfortunately. The best way to mitigate this is to forecast how much that might take in future iterations. But this is a challenging task. You can handle tech debt by splitting some fixed amount of dedicated efforts for each development sprint or having a full sprint once in a quartal. The support is much more challenging to handle, especially if you have legacy service with few people knowing how to work with it. And if you are an infrastructure team (that is my case). It is impossible to foresee the number of bugs, feature requests, and questions from other teams and customers. Each with the highest priority, of course. That can block the development of new features and break all the plans you committed before."}),"\n",(0,a.jsx)(t.p,{children:'The only way I found is to become ruthless in filtering "urgent" support items to complete. No more Mr. Nice Guy. You must become a gateway that needs to be passed so a team will take a support item, not from the queue. I am that guy who will stand against your request, even if it is crucial until you prove it is a real priority. Of course, you can go upstairs and push it through via higher management, but I will fight till the end to protect my team\'s backlog.'}),"\n",(0,a.jsx)(t.p,{children:"Of course, I expected that pressure. But the real tension here is what surprised me."}),"\n",(0,a.jsx)(t.h2,{id:"hell-of-constant-replanning",children:"Hell of constant replanning"}),"\n",(0,a.jsx)(t.p,{children:"Planning is a huge topic I would like to cover in separate essays. For now, I constantly revised a year's roadmap and quarter plans. There are dozens of reasons why that happens, but in the end, I get nothing but frustration."}),"\n",(0,a.jsx)(t.h2,{id:"being-without-mentorship-sucks",children:"Being without mentorship sucks"}),"\n",(0,a.jsx)(t.p,{children:"My quick promotion to a standalone Product Manager happened before my mentor left the organization I am working in. So I stepped into his role and found myself in a vacuum. There is no senior product manager to manage me, and next-level VP management is a bit away from my day-to-day activities. They could help me with my questions. I am not questioning their good attitude. They have a broader view, and diving into a low-level of details is complicated: either because of lacking knowledge in my domain or having a more technical than product-oriented background."}),"\n",(0,a.jsx)(t.p,{children:"That does not mean I am alone and no one wants or can help me. The organization's product management process is well-defined but can't answer all the questions. Asking other PMs gives little as we are acting in a more isolated way and not aware of each other specifics."}),"\n",(0,a.jsx)(t.p,{children:'Recently, Q&A sessions were introduced where I can fire my more-or-less stupid questions and get helpful responses from different audiences: POs, BAs, operational managers, etc. However, I would like a parental figure to sit down with me and say: "Hey, son, stop doing this stupid shit. Here is what I\'d suggest\u2026".'}),"\n",(0,a.jsx)(t.p,{children:"It may be for the best. In another year, I will let you know."}),"\n",(0,a.jsx)(t.h2,{id:"afterword",children:"Afterword"}),"\n",(0,a.jsx)(t.p,{children:"Those are not all insights I have gotten during my first year in a Product Manager's shoes. And not all of them are as negative as I described above. It just appeared when I started writing this piece that the most pessimistic things appeared on the plate. I have gained much experience and still need additional time to analyze some things. I will be glad to share that with you here."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Take care,"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Ilya"})}),"\n",(0,a.jsx)("small",{children:(0,a.jsx)("a",{href:"https://www.vecteezy.com/free-vector/baby",children:"Baby Vectors by Vecteezy"})})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},1632:(e,t,n)=>{n.d(t,{A:()=>o});const o=n.p+"assets/images/pm_year_one-64a361cac61fa9d6eb594d7dc7b36225.jpg"},5512:e=>{e.exports=JSON.parse('{"permalink":"/blog/product-manager-year-one","source":"@site/blog/2022/product-manager-year-one.md","title":"Product Manager: Year One","description":"In this essay, I want to summarize my experience with the insights I collected throughout the year. Some of them might be obvious to a more experienced audience. But for me, some of them were kind of revelations, and some of them were hugely underestimated initially.","date":"2022-05-10T09:30:00.000Z","tags":[{"inline":true,"label":"Product Management","permalink":"/blog/tags/product-management"},{"inline":true,"label":"Community & Insights","permalink":"/blog/tags/community-insights"}],"readingTime":4.91,"hasTruncateMarker":true,"authors":[],"frontMatter":{"date":"2022-05-10T09:30:00.000Z","description":"In this essay, I want to summarize my experience with the insights I collected throughout the year. Some of them might be obvious to a more experienced audience. But for me, some of them were kind of revelations, and some of them were hugely underestimated initially.","slug":"product-manager-year-one","tags":["Product Management","Community & Insights"],"title":"Product Manager: Year One"},"unlisted":false,"prevItem":{"title":"Sidekick product","permalink":"/blog/sidekick-product"},"nextItem":{"title":"Pre-interview tips for Junior Business Analysts","permalink":"/blog/tips-for-junior-ba-interview"}}')},8453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var o=n(6540);const a={},i=o.createContext(a);function s(e){const t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);